const Vsafe = Math.max(Vol, 0.001);
const M1 = n / Vsafe;
const V1 = Vsafe;
const V2 = 2.0;
const M2 = (M1 * V1) / V2;
const W = H.W, Ht = H.H;
function beaker(cx, by, w, h, conc, label, volStr, mStr) {
  H.rect(cx - w/2, by - h, w, h, { stroke: H.colors.axis, width: 2, radius: 4 });
  const cClamped = Math.min(conc, 4) / 4;
  const fillH = h * 0.8;
  H.rect(cx - w/2 + 3, by - fillH, w - 6, fillH - 3, { fill: H.hsl(210, 80, 35 + 30 * cClamped, 0.55) });
  const cnt = Math.max(2, Math.min(14, Math.round(conc * 4)));
  for (let i = 0; i < cnt; i++) {
    const px = cx - w/2 + 10 + ((i * 53) % (w - 20));
    const py = by - 12 - ((i * 37) % (fillH - 24)) + 4 * Math.sin(t * 2 + i);
    H.circle(px, py, 3.5, { fill: H.colors.yellow });
  }
  H.text(label, cx, by + 20, { color: H.colors.ink, size: 13, align: "center", weight: 700 });
  H.text(volStr, cx, by + 38, { color: H.colors.sub, size: 12, align: "center" });
  H.text(mStr, cx, by - h - 12, { color: H.colors.accent, size: 13, align: "center", weight: 700 });
}
const by = Ht - 110;
